<body>
  <main class="wrap">
    <h1>Pocket Garden</h1>
    <p class="lede">Pick what to plant based on the light you have.</p>
    <p class="notice">Your choices reset when you reload this page.</p>

    <fieldset class="filters">
      <legend>Filter plants</legend>
      <button type="button" class="filter-btn" data-filter="all" aria-pressed="true">All plants</button>
      <button type="button" class="filter-btn" data-filter="sun" aria-pressed="false">Loves sun</button>
      <button type="button" class="filter-btn" data-filter="shade" aria-pressed="false">Likes shade</button>
    </fieldset>

