        <h2 id="name-basil">Basil</h2>
        <span class="tag sun">Loves sun</span>
        <p>A fragrant herb that thrives with plenty of warm light.</p>
        <button type="button" class="plant-btn" aria-describedby="name-basil">
          <span class="tick" aria-hidden="true">✓</span><span class="label">Mark as planted</span>
        </button>
      </li>

      <li class="card" data-light="sun" data-name="Sunflower">
        <h2 id="name-sunflower">Sunflower</h2>
        <span class="tag sun">Loves sun</span>
        <p>Tall and cheerful, it follows full sun all day long.</p>
        <button type="button" class="plant-btn" aria-describedby="name-sunflower">
          <span class="tick" aria-hidden="true">✓</span><span class="label">Mark as planted</span>
        </button>
      </li>

      <li class="card" data-light="shade" data-name="Mint">
        <h2 id="name-mint">Mint</h2>
        <span class="tag shade">Likes shade</span>
        <p>A hardy herb that stays lush in cooler, shadier spots.</p>
        <button type="button" class="plant-btn" aria-describedby="name-mint">
          <span class="tick" aria-hidden="true">✓</span><span class="label">Mark as planted</span>
        </button>
      </li>
    </ul>
  </main>

<script>
(function () {
  var cards = Array.prototype.slice.call(document.querySelectorAll('.card'));
  var filterBtns = Array.prototype.slice.call(document.querySelectorAll('.filter-btn'));
  var status = document.getElementById('status');

  function applyFilter(filter) {
    var shown = 0;
    cards.forEach(function (card) {
      var match = filter === 'all' || card.dataset.light === filter;
      card.hidden = !match;
      if (match) shown++;
    });
    filterBtns.forEach(function (b) {
      b.setAttribute('aria-pressed', String(b.dataset.filter === filter));
    });
    status.textContent = 'Showing ' + shown + ' of ' + cards.length + ' plants.';
  }

  filterBtns.forEach(function (b) {
    b.addEventListener('click', function () { applyFilter(b.dataset.filter); });
  });

  cards.forEach(function (card) {
    var btn = card.querySelector('.plant-btn');
    var label = btn.querySelector('.label');
    btn.addEventListener('click', function () {
      var planted = !card.classList.contains('is-planted');
      card.classList.toggle('is-planted', planted);
      btn.classList.toggle('on', planted);
      label.textContent = planted ? 'Planted' : 'Mark as planted';
      status.textContent = card.dataset.name + (planted ? ' marked as planted.' : ' no longer marked as planted.');
    });
  });

  applyFilter('all');
})();
</script>
